if($action==='update_cart'){ $id=(int)($_POST['id']??0);$qty=(int)($_POST['qty']??0);$st=$db->prepare('SELECT stock FROM products WHERE id=? AND active=1');$st->execute([$id]);$stock=$st->fetchColumn();if($qty<=0){unset($_SESSION['cart'][$id]);}elseif($stock!==false){$_SESSION['cart'][$id]=min($qty,(int)$stock);}redirect('index.php?page=cart');}
if($action==='remove'){unset($_SESSION['cart'][(int)($_POST['id']??0)]);redirect('index.php?page=cart');}
if($action==='checkout'){if(!user())redirect('index.php?page=login');$address=trim($_POST['address']??'');if(strlen($address)<8||strlen($address)>1000)throw new Exception('Adresse de livraison invalide.');$cart=$_SESSION['cart']??[];if(!$cart)throw new Exception('Panier vide.');$db->beginTransaction();$items=[];$total=0;foreach($cart as $id=>$qty){$s=$db->prepare('SELECT * FROM products WHERE id=? AND active=1 FOR UPDATE');$s->execute([(int)$id]);$p=$s->fetch();if(!$p||$qty<1||$qty>$p['stock'])throw new Exception('Stock insuffisant pour un article.');$items[]=[$p,$qty];$total+=(float)$p['price']*$qty;}$s=$db->prepare('INSERT INTO orders(user_id,total,address) VALUES(?,?,?)');$s->execute([user()['id'],$total,$address]);$oid=$db->lastInsertId();foreach($items as [$p,$qty]){$db->prepare('INSERT INTO order_items(order_id,product_id,quantity,unit_price) VALUES(?,?,?,?)')->execute([$oid,$p['id'],$qty,$p['price']]);$db->prepare('UPDATE products SET stock=stock-? WHERE id=?')->execute([$qty,$p['id']]);}$db->commit();unset($_SESSION['cart']);flash('Commande #'.$oid.' enregistrée. Paiement à confirmer.');redirect('index.php?page=orders');}
if(str_starts_with($action,'admin_')){if((user()['role']??'')!=='admin')throw new Exception('Accès refusé.');if($action==='admin_product'){$id=(int)($_POST['id']??0);$name=trim($_POST['name']??'');$price=(float)($_POST['price']??-1);$stock=(int)($_POST['stock']??-1);$cat=(int)($_POST['category_id']??0);$image=trim($_POST['image']??'');$validAsset=(bool)preg_match('~^assets/products/[a-zA-Z0-9_.-]+$~',$image);$validScreenshot=str_starts_with($image,'../Screenshots/') && in_array(substr($image,15),$screenshots,true);if(!$name||$price<0||$stock<0||($image&&!$validAsset&&!$validScreenshot))throw new Exception('Informations produit invalides.');if($id){$db->prepare('UPDATE products SET name=?,description=?,price=?,stock=?,category_id=?,image=? WHERE id=?')->execute([$name,$_POST['description']??'',$price,$stock,$cat?:null,$image,$id]);}else{$db->prepare('INSERT INTO products(name,description,price,stock,category_id,image) VALUES(?,?,?,?,?,?)')->execute([$name,$_POST['description']??'',$price,$stock,$cat?:null,$image]);}flash('Produit enregistré.');}elseif($action==='admin_status'){$allowed=['en_attente','confirmee','expediee','livree','annulee'];if(!in_array($_POST['status']??'',$allowed,true))throw new Exception('Statut invalide.');$db->prepare('UPDATE orders SET status=? WHERE id=?')->execute([$_POST['status'],(int)$_POST['id']]);flash('Commande mise à jour.');}elseif($action==='admin_toggle'){$db->prepare('UPDATE products SET active=1-active WHERE id=?')->execute([(int)$_POST['id']]);flash('Visibilité modifiée.');}redirect('index.php?page=admin');}
}catch(Throwable $ex){if($db->inTransaction())$db->rollBack();flash($ex instanceof PDOException?'Opération impossible (email déjà utilisé ou données invalides).':$ex->getMessage());$allowedPages=['home','shop','cart','login','register','product','account','orders','admin'];$return=$_POST['return']??'home';redirect('index.php?page='.(in_array($return,$allowedPages,true)?$return:'home'));}
}
